ALTER TABLE "audit"."events" ADD CONSTRAINT "events_type_known" CHECK ("audit"."events"."type" IN ('sso.registered', 'sso.acs_changed', 'build.started', 'build.succeeded', 'build.failed', 'instance.provisioning', 'instance.starting', 'instance.healthy', 'instance.failed', 'incident.opened', 'ai.key_rotated', 'ai.models_withdrawn', 'instance.retiring', 'instance.retired', 'instance.retire_failed', 'project.created', 'repository.seeded', 'spec.validated', 'token.minted', 'pending_action.created', 'pending_action.confirmed', 'pending_action.rejected', 'pending_action.expired', 'iam_registration.recorded', 'privacy_assessment.recorded', 'iam_registration.submitted', 'privacy_assessment.submitted', 'iam_registration.sent', 'privacy_assessment.sent', 'iam_registration.returned', 'privacy_assessment.returned', 'iam_registration.drafted', 'privacy_assessment.drafted', 'rehearsal.completed', 'release.approved', 'release.approval_rejected', 'approval.requested', 'project.launched', 'repository.pushed', 'repository.history_rewritten', 'repository.visibility_enforced', 'repository.secret_detected', 'repository.scan_incomplete', 'repository.protection_unavailable', 'repository.committed', 'repository.secret_refused', 'app_secret.set', 'app_secret.cleared', 'project.renamed', 'member.added', 'member.removed', 'agent_session.started', 'agent_session.narrowed', 'agent_session.ended', 'sso.deregistered', 'project.archived', 'project.restored', 'project.deleted'));--> statement-breakpoint
ALTER TABLE "iam_registrations" ADD CONSTRAINT "iam_registrations_sent_from" CHECK ((("iam_registrations"."state")::text = 'sent') = ("iam_registrations"."sent_from" IS NOT NULL) AND ("iam_registrations"."sent_from" IS NULL OR "iam_registrations"."sent_from" IN ('draft', 'change_requested', 'expired', 'active')));--> statement-breakpoint
ALTER TABLE "iam_registrations" ADD CONSTRAINT "iam_registrations_sent_by" CHECK (("iam_registrations"."state")::text <> 'sent' OR ("iam_registrations"."sent_at" IS NOT NULL AND "iam_registrations"."sent_by" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "privacy_assessments" ADD CONSTRAINT "privacy_assessments_sent" CHECK (("privacy_assessments"."state")::text <> 'sent' OR ("privacy_assessments"."sent_at" IS NOT NULL AND "privacy_assessments"."sent_by" IS NOT NULL AND "privacy_assessments"."gap_answers" IS NOT NULL));